package com.zest.products.auth;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="refresh_token",indexes=@Index(name="idx_refresh_token_value",columnList="token",unique=true)) public class RefreshToken { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private AppUser user; @Column(nullable=false,unique=true,length=120) private String token; @Column(nullable=false) private Instant expiresAt; @Column(nullable=false) private boolean revoked; public AppUser getUser(){return user;} public void setUser(AppUser v){user=v;} public String getToken(){return token;} public void setToken(String v){token=v;} public Instant getExpiresAt(){return expiresAt;} public void setExpiresAt(Instant v){expiresAt=v;} public boolean isRevoked(){return revoked;} public void setRevoked(boolean v){revoked=v;} }
